import{z as C,x as l,o as A,c as s,q as t,j as n,D as a,d as B,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"数字货币的理论","description":"","frontmatter":{"title":"数字货币的理论","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mt-digital-currency-theory.md","filePath":"econ/mt-digital-currency-theory.md","lastUpdated":1791413859000}'),D={name:"econ/mt-digital-currency-theory.md"};function d(p,E,m,c,F,h){const r=l("Mermaid");return A(),s("div",null,[E[2]||(E[2]=t('<h1 id="数字货币的理论" tabindex="-1">数字货币的理论 <a class="header-anchor" href="#数字货币的理论" aria-label="Permalink to &quot;数字货币的理论&quot;">​</a></h1><div class="epigraph"><p>货币是一套记账与结算的安排；数字化的真问题不是要不要，而是由谁记账、记录带不带身份、以及计息到多负。</p><footer>—— 据 Brunnermeier–Niepelt 2019；BIS 对 CBDC 的综述整理</footer></div><p><a href="/econ/mt-qe-theory">上一课</a>把负债侧的第一种扩张——买资产——还原为对摩擦的针对性松绑。负债侧还有更激进的一步：央行绕开银行，直接对公众发行负债，这就是 CBDC。基线课的<a href="/econ/cbdc">CBDC</a>已给出类型学、挤兑与走廊争夺的要点；本课深化它的理论骨架：公共货币与私人货币的等价性基准、替代对象决定效应、以及计息货币对利率下限的重写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理论起点是把货币看成记录技术。现金是匿名的代币式记录——谁持有谁拥有；存款是商业银行的账户记录——转账改的是账。CBDC 是央行账户（或央行代币）对公众开放，于是<a href="/econ/money-as-medium">货币层次与支付</a>里由存款与现金分掌的记录职能，第一次出现了央行的直接版本。Brunnermeier–Niepelt 2019 给出等价性基准：在完全市场与同等执行技术下，公共发行与私人发行支持相同配置。与 QE 的无关性定理同构，这是纪律而非否定：<strong>CBDC 的一切实质效应，必须由某个具体摩擦承担</strong>——支付市场的垄断、执行技术差异、或挤兑。</p><p><span class="marginnote">「等价性基准」翻译成大白话：先证明在无摩擦的完美世界里，央行发币与银行发币结果一样。于是任何「CBDC 必然改变什么」的说法，都必须指出是哪个具体摩擦在起作用，否则就是空谈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一个要钉住的变量是替代对象，效应随它完全改变。</p><p>替代现金：只是记录技术升级，宏观含义近零。替代存款：银行融资被抽走，贷款端如何反应取决于银行能否用其他负债补位；Keister–Sanches 的结论是双向的——存款利率因竞争上升，贷款可能收缩，福利不定。替代货币基金：公众获得对手方地位的央行负债，准备金市场的量价关系被改写，这正是基线课「争夺走廊」的来源。</p><p><span class="marginnote">常见误区：以为 CBDC 就是「央行抢银行的生意」。替代现金只是技术升级；对银行冲击多大，取决于存款搬家后银行能否用其他负债补位——理论结论是「福利不定」，不是必然的信贷收缩。</span></p><p>第二个变量是计息。现金的名义回报被制度固定为零且不可销毁，这是利率下限的技术根源（Eggertsson–Woodford 2003 已点明）：存款利率被拉到显著为负时，公众换持现金，宽松失效。可计息的 CBDC 若最终替代现金，这个逃逸通道被关闭，有效下限原则上可以移除——负利率从修辞变成工具。</p>',11)),(A(),n(i,null,{default:a(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22%E8%B4%A7%E5%B8%81%20%3D%20%E8%AE%B0%E5%BD%95%E6%8A%80%E6%9C%AF%22%5D%20--%3E%20T1%5B%22%E7%8E%B0%E9%87%91%EF%BC%9A%E5%8C%BF%E5%90%8D%E4%BB%A3%E5%B8%81%22%5D%0A%20%20REC%20--%3E%20T2%5B%22%E5%AD%98%E6%AC%BE%EF%BC%9A%E9%93%B6%E8%A1%8C%E8%B4%A6%E6%88%B7%22%5D%0A%20%20REC%20--%3E%20T3%5B%22CBDC%EF%BC%9A%E5%A4%AE%E8%A1%8C%E5%AF%B9%E5%85%AC%E4%BC%97%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20EQ%5B%22%E7%AD%89%E4%BB%B7%E6%80%A7%E5%9F%BA%E5%87%86%EF%BC%9A%E5%90%8C%E9%85%8D%E7%BD%AE%22%5D%20--%3E%20Q%7B%22%E6%9B%BF%E4%BB%A3%E8%B0%81%22%7D%0A%20%20Q%20--%3E%7C%22%E7%8E%B0%E9%87%91%22%7C%20UP%5B%22%E6%8A%80%E6%9C%AF%E5%8D%87%E7%BA%A7%EF%BC%8C%E5%AE%8F%E8%A7%82%E8%BF%91%E9%9B%B6%22%5D%0A%20%20Q%20--%3E%7C%22%E5%AD%98%E6%AC%BE%22%7C%20BANK%5B%22%E9%93%B6%E8%A1%8C%E8%9E%8D%E8%B5%84%E6%90%AC%E5%AE%B6%EF%BC%8C%E7%A6%8F%E5%88%A9%E4%B8%8D%E5%AE%9A%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B4%A7%E5%9F%BA%22%7C%20COR%5B%22%E8%B5%B0%E5%BB%8A%E4%BA%89%E5%A4%BA%EF%BC%9A%E9%87%8F%E4%BB%B7%E5%86%85%E7%94%9F%22%5D%0A%20%20INT%7B%22%E6%98%AF%E5%90%A6%E8%AE%A1%E6%81%AF%22%7D%20--%3E%20ZLB%5B%22%E6%9B%BF%E4%BB%A3%E7%8E%B0%E9%87%91%E5%90%8E%E4%B8%8B%E9%99%90%E5%8F%AF%E7%A7%BB%E9%99%A4%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[B("计息与下限的机制值得单独展开。第一课的"),e("a",{href:"/econ/mt-optimal-inflation"},"Friedman 规则"),B("与下限保险的张力，在可计息货币体系里被重新谈判：既然有效下限来自现金这个不可计息的替代品，那么消灭现金与取消下限是同一个决定的两面。下限消失后，衰退期的宽松不再受零约束，第一课里「为下限买保险而维持正通胀」的理由被削弱——最优通胀问题在数字货币世界里要重新作答。")],-1)),(A(),n(i,null,{default:a(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEG%5B%22%E8%A1%B0%E9%80%80%E6%9C%9F%E9%9C%80%E8%A6%81%E6%98%BE%E8%91%97%E4%B8%BA%E8%B4%9F%E7%9A%84%E5%88%A9%E7%8E%87%22%5D%20--%3E%20SWAP%5B%22%E5%85%AC%E4%BC%97%E6%8D%A2%E6%8C%81%E9%9B%B6%E6%81%AF%E7%8E%B0%E9%87%91%EF%BC%8C%E5%AE%BD%E6%9D%BE%E5%A4%B1%E6%95%88%22%5D%0A%20%20SWAP%20--%3E%20ZLB%5B%22%E6%9C%89%E6%95%88%E4%B8%8B%E9%99%90%E5%8D%A1%E4%BD%8F%E6%94%BF%E7%AD%96%22%5D%0A%20%20CBD%5B%22%E8%AE%A1%E6%81%AF%20CBDC%20%E6%9B%BF%E4%BB%A3%E7%8E%B0%E9%87%91%22%5D%20--%3E%20CLOSE%5B%22%E9%80%83%E9%80%B8%E9%80%9A%E9%81%93%E8%A2%AB%E5%85%B3%E9%97%AD%22%5D%0A%20%20CLOSE%20--%3E%20NOLB%5B%22%E4%B8%8B%E9%99%90%E5%8E%9F%E5%88%99%E4%B8%8A%E5%8F%AF%E7%A7%BB%E9%99%A4%22%5D%0A%20%20NOLB%20--%3E%20TOOL%5B%22%E8%B4%9F%E5%88%A9%E7%8E%87%E4%BB%8E%E4%BF%AE%E8%BE%9E%E5%8F%98%E6%88%90%E5%B7%A5%E5%85%B7%22%5D%0A%20%20NOLB%20--%3E%20WEAK%5B%22%E3%80%8C%E7%BB%B4%E6%8C%81%E6%AD%A3%E9%80%9A%E8%83%80%E4%B9%B0%E4%BF%9D%E9%99%A9%E3%80%8D%E7%9A%84%E7%90%86%E7%94%B1%E8%A2%AB%E5%89%8A%E5%BC%B1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p>账户式记录携带身份，代币式记录携带匿名，这是设计参数而非附加功能：身份记录改善税收执行与反洗钱，也把支付行为变成可监测数据；匿名代币保留隐私，也保留通胀税的逃逸口。货币理论在这里与公共财政接壤：通胀税的可行性依赖于不可匿名化的货币基础。</p><p><span class="marginnote">等价性定理与 Wallace 1981 在方法论上是同一枚硬币：先写无摩擦时公共与私人货币无差别，再逐个引入摩擦解释观察到的差异。跳过基准直接论证「CBDC 必然改变什么」，与跳过基准论证「QE 必然有效」是同一种错误。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>网络效应与转换成本让「原则上」与「实际上」之间隔着强路径依赖：支付习惯、商户接受、跨境使用都不随政策一步切换。离境与货币替代——他国公众持有本币 CBDC 带来的输送效应——属于国际货币体系的深化，本课不展开；挤兑动态在基线课已给出结构，这里只补一句机制来源：计息 CBDC 相当于给<a href="/econ/diamond-dybvig">存款人</a>一个常备的外部期权，挤兑的触发阈值因此系统性左移。下一课回到最古典的环节：无论负债发给谁，央行怎样把市场利率钉在它宣布的位置。</p><p><span class="marginnote">直觉类比：计息 CBDC 像给每个存款人配了一本「随时可划转的央行存折」。银行一有风吹草动，存款人动动手指就能换过去——挤兑从「排队取现」变成「一键转账」，触发阈值自然左移。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>等价性基准先行：摩擦决定效应，CBDC 不是自带宏观力量的新资产。</li><li>替代对象是第一个变量：替代现金近零，替代存款福利不定，替代货基改写走廊。</li><li>下限的技术根源是零息现金；可计息 CBDC 使取消下限与消灭现金成为同一决定。</li><li>隐私是设计参数：身份记录换税收执行，匿名代币保留通胀税逃逸口。</li><li>出处：Brunnermeier–Niepelt 2019；Keister–Sanches 2023；Eggertsson–Woodford 2003；BIS CBDC 综述。</li></ul>',7))])}const _=C(D,[["render",d]]);export{f as __pageData,_ as default};
